class TestRunFiles:
    def test_stable_paths_per_project(self, run_dir):
        a = cli._run_files("/some/project")
        b = cli._run_files("/some/project")
        c = cli._run_files("/other/project")
        assert a == b
        assert a["log"] != c["log"]
        assert set(a) == {"log", "exit", "pid"}

    def test_run_dir_is_owner_only(self, run_dir):
        files = cli._run_files("/some/project")
        mode = files["log"].parent.stat().st_mode & 0o777
        assert mode == 0o700


