class TestDetach:
    def test_detach_spawns_and_records_pid(self, run_dir, monkeypatch, capsys):
        captured = {}

        class FakeProc:
            pid = 4242

        def fake_popen(argv, **kwargs):
            captured["argv"] = argv
            captured["kwargs"] = kwargs
            return FakeProc()

        monkeypatch.setattr(subprocess, "Popen", fake_popen)
        rc = cli.main(["--detach", "--pr", "7", "--project-root", "/some/project"])
        assert rc == 0
        assert "--detach" not in captured["argv"]
        assert "--pr" in captured["argv"]
        assert captured["kwargs"]["start_new_session"] is True
        files = cli._run_files("/some/project")
        assert files["pid"].read_text() == "4242"
        assert "review started (pid 4242)" in capsys.readouterr().out

    def test_detach_refuses_when_already_running(self, run_dir, monkeypatch):
        files = cli._run_files("/some/project")
        files["log"].write_text("running\n")
        files["pid"].write_text(str(os.getpid()))  # a live pid
        rc = cli.main(["--detach", "--project-root", "/some/project"])
        assert rc == 2

    def test_stale_pid_is_reclaimed(self, run_dir, monkeypatch):
        files = cli._run_files("/some/project")
        files["pid"].write_text("999999999")  # dead pid

        class FakeProc:
            pid = 777

        monkeypatch.setattr(subprocess, "Popen", lambda *a, **k: FakeProc())
        rc = cli.main(["--detach", "--project-root", "/some/project"])
        assert rc == 0
        assert files["pid"].read_text() == "777"

    def test_claim_is_exclusive(self, run_dir):
        files = cli._run_files("/p2")
        assert cli._claim_run(files) is True
        files["log"].write_text("x")
        # Second claim while first holder alive-marker absent: pid file
        # exists but empty -> _pid_alive None -> stale -> reclaimed.
        assert cli._claim_run(files) is True


class TestWait:
    def _args(self, project, timeout=1):
        return argparse.Namespace(project_root=project, wait_timeout_s=timeout)

    def test_done_replays_log_and_exit_code(self, run_dir, capsys):
        files = cli._run_files("/p")
        files["log"].write_text("line1\nsummary line\n")
        files["exit"].write_text("0")
        assert cli._wait(self._args("/p")) == 0
        out = capsys.readouterr().out
        assert "summary line" in out
        assert "exit code 0" in out

    def test_nonzero_exit_propagates(self, run_dir):
        files = cli._run_files("/p")
        files["log"].write_text("boom\n")
        files["exit"].write_text("1")
        assert cli._wait(self._args("/p")) == 1

    def test_nothing_started(self, run_dir):
        assert cli._wait(self._args("/p")) == 2

    def test_still_running_returns_3(self, run_dir):
        files = cli._run_files("/p")
        files["log"].write_text("working\n")
        files["pid"].write_text(str(os.getpid()))  # alive
        start = time.monotonic()
        assert cli._wait(self._args("/p", timeout=1)) == cli.EXIT_STILL_RUNNING
        elapsed = time.monotonic() - start
        assert 1 <= elapsed < 3  # respects small timeouts, no 5s overshoot

    def test_dead_child_without_exit_file_is_failure(self, run_dir, capsys):
        files = cli._run_files("/p")
        files["log"].write_text("started\nthen died\n")
        files["pid"].write_text("999999999")  # not a real pid
        assert cli._wait(self._args("/p")) == 1
        assert "died without completing" in capsys.readouterr().out


class TestMainExitCodes:
    def test_pipeline_error_exits_1(self, monkeypatch, capsys):
        def boom(options):
            raise cli.pipeline.PipelineError("stage failed")

        monkeypatch.setattr(cli.pipeline, "run_review", boom)
        assert cli.main(["--dry-run"]) == 1
        assert "ERROR: stage failed" in capsys.readouterr().err

    def test_unexpected_exception_exits_1_with_error_line(self, monkeypatch, capsys):
        def boom(options):
            raise ValueError("surprise")

        monkeypatch.setattr(cli.pipeline, "run_review", boom)
        assert cli.main(["--dry-run"]) == 1
        assert "ERROR: unexpected failure: surprise" in capsys.readouterr().err

    def test_wait_timeout_must_be_positive(self):
        with pytest.raises(SystemExit):
            cli.main(["--wait", "--wait-timeout-s", "0"])


